from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for color in set(v for row in grid for v in row):
        if color == bg:
            continue
        points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for r, c in points:
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color):
                    continue
                # Extend the diagonal through an adjacent matching pair in both directions.
                for ar, ac, sr, sc in ((r, c, -dr, -dc), (rr, cc, dr, dc)):
                    while 0 <= ar + sr < h and 0 <= ac + sc < w:
                        ar += sr
                        ac += sc
                        if grid[ar][ac] != bg:
                            break
                        out[ar][ac] = color
    return out

